sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?founder ?birthPlace
WHERE {
  dbr:Vermont_Studio_Center dbp:founder ?founder .
  OPTIONAL { ?founder dbp:birthPlace ?birthPlace . }
  OPTIONAL { ?founder dbo:birthPlace ?birthPlace2 . }
  BIND (COALESCE(?birthPlace, ?birthPlace2) AS ?birthPlace)
}
LIMIT 100

